#include <stdio.h>
#include <stdlib.h>
#define MAXN 10005

int heap[MAXN];
int size = 0;

// 小根堆 上浮
void up(int idx)
{
    while (idx > 1)
    {
        int fa = idx / 2;
        if (heap[fa] > heap[idx])
        {
            int t = heap[fa];
            heap[fa] = heap[idx];
            heap[idx] = t;
            idx = fa;
        }
        else break;
    }
}

// 小根堆 下沉
void down(int idx)
{
    while (idx * 2 <= size)
    {
        int l = idx * 2, r = idx * 2 + 1;
        int min = l;
        if (r <= size && heap[r] < heap[l]) min = r;
        if (heap[idx] > heap[min])
        {
            int t = heap[idx];
            heap[idx] = heap[min];
            heap[min] = t;
            idx = min;
        }
        else break;
    }
}

// 插入堆
void push(int x)
{
    heap[++size] = x;
    up(size);
}

// 取出最小值
int pop()
{
    int res = heap[1];
    heap[1] = heap[size--];
    down(1);
    return res;
}

int main()
{
    int n;
    scanf("%d", &n);
    for (int i = 0; i < n; i++)
    {
        int x;
        scanf("%d", &x);
        push(x);
    }
    long long total = 0;
    while (size > 1)
    {
        int a = pop();
        int b = pop();
        int sum = a + b;
        total += sum;
        push(sum);
    }
    printf("%lld\n", total);
    return 0;
}
